; // Douglas-Peucker algorithm function douglasPeucker(points, eps) { if (points.length < 3) return points; // Find point furthest from line segment let maxDist = 0; let maxIndex = 0; const first = points[0]; const last = points[points.length - 1]; for (let i = 1; i < points.length - 1; i++) { const pt = points[i]; // Distance from point to line const dx = last.x - first.x; const dy = last.y - first.y; const norm = Math.sqrt(dx * dx + dy * dy); let dist; if (norm < 0.001) { // Line is a point const dx2 = pt.x - first.x; const dy2 = pt.y - first.y; dist = Math.sqrt(dx2 * dx2 + dy2 * dy2); } else { // Perpendicular distance dist = Math.abs((dy * pt.x - dx * pt.y + last.x * first.y - last.y * first.x) / norm); } if (dist > maxDist) { maxDist = dist; maxIndex = i; } } // If max distance is greater than epsilon, recursively simplify if (maxDist > eps) { const left = douglasPeucker(points.slice(0, maxIndex + 1), eps); const right = douglasPeucker(points.slice(maxIndex), eps); return left.slice(0, -1).concat(right); } else { return [first, last]; } } // Apply Douglas-Peucker let simplified = douglasPeucker(path, epsilon); // Remove segments shorter than minSegmentLength const filtered = [simplified[0]]; for (let i = 1; i < simplified.length; i++) { const prev = filtered[filtered.length - 1]; const curr = simplified[i]; const dx = curr.x - prev.x; const dy = curr.y - prev.y; const segLength = Math.sqrt(dx * dx + dy * dy); if (segLength >= minSegmentLength || i === simplified.length - 1) { filtered.push(curr); } } // 🔧 REV18: Ensure path is closed (Moore-Neighbor always produces closed paths) // Add first point at end if not already there if (filtered.length >= 3) { const first = filtered[0]; const last = filtered[filtered.length - 1]; const closureDist = Math.sqrt( Math.pow(last.x - first.x, 2) + Math.pow(last.y - first.y, 2) ); // If not closed, add first point to close it if (closureDist > 1.0) { filtered.push({ x: first.x, y: first.y }); } } return filtered; } /** * Extract solid regions from grayscale image * Returns both paths and a mask for dot exclusion * * 🔧 REV18: MAJOR REWRITE - Moore-Neighbor boundary tracing * - STEP 1: Aggressive pre-threshold smoothing (adaptive, 2.5% of diagonal, min 12px) * - STEP 2: Solid thresholding on smoothed image * - STEP 3: Morphological CLOSING (dilate→erode) to kill thin ribbons <6px wide * - STEP 4: Minimum area filter (prevents degenerate contours) * - STEP 5: Moore-Neighbor boundary tracing (REPLACES marching squares) */ function extractSolidRegions(imageData, threshold, blurRadius, minArea, varianceThreshold = 0.02, portraitContext = null) { const { width, height, data } = imageData; // 🔧 CRITICAL: Create grayscale WITH ALPHA HANDLING // Alpha=0 (transparent) MUST be treated as WHITE, not black! let grayData = new ImageData(width, height); let alphaZeroCount = 0; let lumMin = 1, lumMax = 0; for (let i = 0; i < data.length; i += 4) { const r = data[i]; const g = data[i + 1]; const b = data[i + 2]; const a = data[i + 3]; let lum; if (a < 128) { // 🔧 CRITICAL: Transparent pixels = WHITE (luminance 1.0) lum = 1.0; alphaZeroCount++; } else { // Blend with white background based on alpha const alphaFactor = a / 255; const blendedR = r * alphaFactor + 255 * (1 - alphaFactor); const blendedG = g * alphaFactor + 255 * (1 - alphaFactor); const blendedB = b * alphaFactor + 255 * (1 - alphaFactor); lum = getLuminance(blendedR, blendedG, blendedB); } lumMin = Math.min(lumMin, lum); lumMax = Math.max(lumMax, lum); const gray = Math.round(lum * 255); grayData.data[i] = gray; grayData.data[i+1] = gray; grayData.data[i+2] = gray; grayData.data[i+3] = 255; } console.log([extractSolidRegions] Alpha stats: ${alphaZeroCount} transparent pixels (treated as white)); console.log([extractSolidRegions] Luminance range: ${lumMin.toFixed(3)} - ${lumMax.toFixed(3)}); const portraitMode = halftoneMode.enableSubjectIsolation && !!portraitContext; const enableThreeToneModel = portraitMode && portraitContext.enableThreeT